// ===========================================================================
// NCBTransactionQueue 家族 UT：两个单态化变体各一对 DUT（golden <M> 对重写
// <M>_xs），共享时钟/复位，各自独立随机激励，逐拍比对**全部**输出端口。
//
// ★激励为什么不是「每个输入独立均匀随机」★
// 本模块的判别力全在「同一个槽上多个事件撞车」：分配撞释放、分配撞 opDone、
// WriteDataCancel 撞 BRESP、R/W/allocate 三方抢同一份 axi Critical、前序依赖
// 指向的槽正好本拍释放。槽号 64/32 路、每个 strobe 各自独立均匀随机的话，
// 两路撞同一槽的概率低到 200k 拍也凑不出几次 —— 那样的 errors=0 什么都没验到。
// （上一轮 StoreQueue 的教训：604 个输入每拍独立均匀随机，3 seed × 200k 全绿，
//   实际什么都没验。）
// 所以每拍先掷一个**焦点槽号** focus（65% 落在 0..3 的小池子），再让各路 strobe
// 以 45% 的概率一热地打在 focus 上 —— 撞车因此是常态而不是巧合。
// strobe 掩码还按 12% 给全零、10% 给多热、8% 给随机掩码，专打 ParallelMux
// (OR-of-AND 一热多路) 在非一热输入下的行为：全零读出 0、多热读出按位或。
//
// ★暖机（本模块必须有）★
// golden 每槽 34 个寄存器里**只有 14/15 个在复位域**，另外 20 个（info / 两个
// 地址 / Size / Len / Device / 两组 Critical+Count / order）一个都不复位。
// +vcs+initreg 给两个 DUT 的这些寄存器**各掷各的随机值**，不暖机的话第一拍就
// 会因为初值不同而报错。所以复位撤销后先用 2 拍「alloc_en=1 + strb 全 1、其余
// strobe 全 0」把每个槽的每个不复位寄存器都写成确定值，之后才打开比较。
// ★暖机之后必须复核变异仍能被抓到★ —— 见 mutants.py，每个变异体的 errors 数
// 都记在那里。
//
// ★覆盖证据★
// tb 统计若干「有判别力的事件」计数（见 COVERAGE 段），任何一项为 0 都说明对应
// 机制根本没被激励到，这一轮 errors=0 不作数。计数用到少量对 golden 内部寄存器
// 的层次引用（tb 里允许，且只用于计数，不参与判决）。
//
// 自动生成：verif/ut/NCBTransactionQueue/gen.py —— 勿手改
// ===========================================================================
`timescale 1ns/1ps

module tb;

  int unsigned NCYCLES = 200000;
  bit   clk = 0;
  logic rst;
  logic cmp_en = 1'b0;   // 暖机结束前不比较（见文件头）
  int errors = 0;
  longint checks = 0;
  int unsigned warm = 0;
  // 中途异步复位的次数（见 initial 块）。
  localparam int RESET_PULSES = 20;
  longint cov_reset_pulses = 0;

  always #5 clk = ~clk;

  // strobe 取值：45% 一热打在焦点槽、25% 一热随机、12% 全零、10% 多热、8% 随机掩码。
  function automatic logic [63:0] strb_pick(input int unsigned n,
                                            input int unsigned focus);
    logic [63:0] m;
    logic [63:0] lim;
    int unsigned r;
    r = $urandom_range(0, 99);
    lim = (n >= 64) ? 64'hFFFF_FFFF_FFFF_FFFF : ((64'd1 << n) - 64'd1);
    if (r < 45)      m = 64'd1 << focus;
    else if (r < 70) m = 64'd1 << $urandom_range(0, n - 1);
    else if (r < 82) m = 64'd0;
    else if (r < 92) m = (64'd1 << focus) | (64'd1 << $urandom_range(0, n - 1));
    else             m = {$urandom(), $urandom()};
    return m & lim;
  endfunction

  // op 位偏稀疏：全 0 的分配会让槽在下一拍立刻释放，这正是要打的边界。
  function automatic logic op_bit();
    return ($urandom_range(0, 99) < 30);
  endfunction

