  int unsigned q64_focus;
  int unsigned q64_drain = 0;   // 排空突发剩余拍数
  logic [63:0] q64_alloc_hit;
  assign q64_alloc_hit = {64{q64_io_allocate_en}} & q64_alloc_strb;

  always @(negedge clk) begin
    q64_focus = ($urandom_range(0, 99) < 65) ? $urandom_range(0, 3)
                                             : $urandom_range(0, 64 - 1);
    if (warm < 2) begin
      // 暖机：一拍把每个槽都分配一遍，把 20 个不复位寄存器写成确定值；
      // 其余 strobe / en 全 0，免得 op 位的次态去读还是 X 的 Count。
      q64_io_allocate_en  <= 1'b1;
      q64_alloc_strb      <= {64{1'b1}};
      q64_rxdat_query_strb <= '0;
      q64_rxdat_cancel_strb <= '0;
      q64_rxdat_write_data_strb <= '0;
      q64_txrsp_op_read_strb <= '0;
      q64_txrsp_op_done_strb <= '0;
      q64_txrsp_info_read_strb <= '0;
      q64_txdat_op_read_strb <= '0;
      q64_txdat_op_done_strb <= '0;
      q64_txdat_info_read_strb <= '0;
      q64_txdat_operand_read_strb <= '0;
      q64_txdat_operand_write_strb <= '0;
      q64_aw_op_ponr_strb <= '0;
      q64_aw_info_read_strb <= '0;
      q64_aw_operand_read_strb <= '0;
      q64_w_op_ponr_strb <= '0;
      q64_w_operand_read_strb <= '0;
      q64_w_operand_write_strb <= '0;
      q64_b_op_done_strb <= '0;
      q64_ar_op_ponr_strb <= '0;
      q64_ar_info_read_strb <= '0;
      q64_ar_operand_read_strb <= '0;
      q64_r_op_done_strb <= '0;
      q64_r_operand_read_strb <= '0;
      q64_r_operand_axi_write_strb <= '0;
      q64_io_upstreamRxDat_query_en <= 1'b0;
      q64_io_upstreamRxDat_cancel_en <= 1'b0;
      q64_io_upstreamRxDat_writeData_en <= 1'b0;
    end else if (q64_drain == 3) begin
      // 排空第 1 拍：把所有槽的 chi Count 写成 0 —— CompData 的清除只在
      // Count==0 时发生，不先压平就永远排不空。
      q64_io_allocate_en <= 1'b0;
      q64_alloc_strb <= '0;
      q64_txdat_operand_write_strb <= {64{1'b1}};
      q64_rxdat_query_strb <= '0;
      q64_rxdat_cancel_strb <= '0;
      q64_rxdat_write_data_strb <= '0;
      q64_txrsp_op_read_strb <= '0;
      q64_txrsp_op_done_strb <= '0;
      q64_txrsp_info_read_strb <= '0;
      q64_txdat_op_read_strb <= '0;
      q64_txdat_op_done_strb <= '0;
      q64_txdat_info_read_strb <= '0;
      q64_txdat_operand_read_strb <= '0;
      q64_aw_op_ponr_strb <= '0;
      q64_aw_info_read_strb <= '0;
      q64_aw_operand_read_strb <= '0;
      q64_w_op_ponr_strb <= '0;
      q64_w_operand_read_strb <= '0;
      q64_w_operand_write_strb <= '0;
      q64_b_op_done_strb <= '0;
      q64_ar_op_ponr_strb <= '0;
      q64_ar_info_read_strb <= '0;
      q64_ar_operand_read_strb <= '0;
      q64_r_op_done_strb <= '0;
      q64_r_operand_read_strb <= '0;
      q64_r_operand_axi_write_strb <= '0;
      q64_io_upstreamRxDat_query_en <= 1'b0;
      q64_io_upstreamRxDat_cancel_en <= 1'b0;
      q64_io_upstreamRxDat_writeData_en <= 1'b0;
      q64_drain <= q64_drain - 1;
    end else if (q64_drain != 0) begin
      // 排空第 2/3 拍：所有清除 strobe 全 1、所有 done 位全 1、Cancel 也拉起，
      // 两拍后 op 位全清、free_strb 全 1，再一拍 valid 全清 —— 队列见底。
      // 这也是**多热 strobe** 的重灾区，正好顺带打 ParallelMux 的非一热行为。
      q64_io_allocate_en <= 1'b0;
      q64_alloc_strb <= '0;
      q64_rxdat_query_strb <= {64{1'b1}};
      q64_rxdat_cancel_strb <= {64{1'b1}};
      q64_rxdat_write_data_strb <= {64{1'b1}};
      q64_txrsp_op_read_strb <= {64{1'b1}};
      q64_txrsp_op_done_strb <= {64{1'b1}};
      q64_txrsp_info_read_strb <= {64{1'b1}};
      q64_txdat_op_read_strb <= {64{1'b1}};
      q64_txdat_op_done_strb <= {64{1'b1}};
      q64_txdat_info_read_strb <= {64{1'b1}};
      q64_txdat_operand_read_strb <= {64{1'b1}};
      q64_txdat_operand_write_strb <= {64{1'b1}};
      q64_aw_op_ponr_strb <= {64{1'b1}};
      q64_aw_info_read_strb <= {64{1'b1}};
      q64_aw_operand_read_strb <= {64{1'b1}};
      q64_w_op_ponr_strb <= {64{1'b1}};
      q64_w_operand_read_strb <= {64{1'b1}};
      q64_w_operand_write_strb <= {64{1'b1}};
      q64_b_op_done_strb <= {64{1'b1}};
      q64_ar_op_ponr_strb <= {64{1'b1}};
      q64_ar_info_read_strb <= {64{1'b1}};
      q64_ar_operand_read_strb <= {64{1'b1}};
      q64_r_op_done_strb <= {64{1'b1}};
      q64_r_operand_read_strb <= {64{1'b1}};
      q64_r_operand_axi_write_strb <= {64{1'b1}};
      q64_io_upstreamRxDat_query_en <= 1'b1;
      q64_io_upstreamRxDat_cancel_en <= 1'b1;
      q64_io_upstreamRxDat_writeData_en <= 1'b1;
      q64_drain <= q64_drain - 1;
    end else begin
      q64_io_allocate_en <= ($urandom_range(0, 99) < 55);
      q64_alloc_strb <= strb_pick(64, q64_focus);
      q64_rxdat_query_strb <= strb_pick(64, q64_focus);
      q64_rxdat_cancel_strb <= strb_pick(64, q64_focus);
      q64_rxdat_write_data_strb <= strb_pick(64, q64_focus);
      q64_txrsp_op_read_strb <= strb_pick(64, q64_focus);
      q64_txrsp_op_done_strb <= strb_pick(64, q64_focus);
      q64_txrsp_info_read_strb <= strb_pick(64, q64_focus);
      q64_txdat_op_read_strb <= strb_pick(64, q64_focus);
      q64_txdat_op_done_strb <= strb_pick(64, q64_focus);
      q64_txdat_info_read_strb <= strb_pick(64, q64_focus);
      q64_txdat_operand_read_strb <= strb_pick(64, q64_focus);
      q64_txdat_operand_write_strb <= strb_pick(64, q64_focus);
      q64_aw_op_ponr_strb <= strb_pick(64, q64_focus);
      q64_aw_info_read_strb <= strb_pick(64, q64_focus);
      q64_aw_operand_read_strb <= strb_pick(64, q64_focus);
      q64_w_op_ponr_strb <= strb_pick(64, q64_focus);
      q64_w_operand_read_strb <= strb_pick(64, q64_focus);
      q64_w_operand_write_strb <= strb_pick(64, q64_focus);
      q64_b_op_done_strb <= strb_pick(64, q64_focus);
      q64_ar_op_ponr_strb <= strb_pick(64, q64_focus);
      q64_ar_info_read_strb <= strb_pick(64, q64_focus);
      q64_ar_operand_read_strb <= strb_pick(64, q64_focus);
      q64_r_op_done_strb <= strb_pick(64, q64_focus);
      q64_r_operand_read_strb <= strb_pick(64, q64_focus);
      q64_r_operand_axi_write_strb <= strb_pick(64, q64_focus);
      q64_io_upstreamRxDat_query_en <= ($urandom_range(0, 99) < 50);
      q64_io_upstreamRxDat_cancel_en <= ($urandom_range(0, 99) < 50);
      q64_io_upstreamRxDat_writeData_en <= ($urandom_range(0, 99) < 50);
      // 每 ~125 拍来一次三拍排空突发：没有它，被暖机填满的 64 个槽里
      // 焦点池之外的那些永远等不到 done，队列全空/见底这类边界一次也打不到。
      if ($urandom_range(0, 999) < 8) q64_drain <= 3;
    end
    // 载荷与 op 位每拍都换（暖机/排空拍也换，两个 DUT 共用同一份输入）
    q64_io_allocate_bits_op_chi_Comp_valid <= op_bit();
    q64_io_allocate_bits_op_chi_Comp_barrier_CHICancelOrAXIBresp <= op_bit();
    q64_io_allocate_bits_op_chi_DBIDResp_valid <= op_bit();
    q64_io_allocate_bits_op_chi_CompDBIDResp_valid <= op_bit();
    q64_io_allocate_bits_op_chi_ReadReceipt_valid <= op_bit();
    q64_io_allocate_bits_op_chi_CompData_valid <= op_bit();
    q64_io_allocate_bits_op_chi_CompData_sep <= op_bit();
    q64_io_allocate_bits_op_axi_WriteAddress_valid <= op_bit();
    q64_io_allocate_bits_op_axi_WriteAddress_barrier_CHIWriteBackData <= op_bit();
    q64_io_allocate_bits_op_axi_WriteData_valid <= op_bit();
    q64_io_allocate_bits_op_axi_WriteResponse_valid <= op_bit();
    q64_io_allocate_bits_op_axi_ReadAddress_valid <= op_bit();
    q64_io_allocate_bits_op_axi_ReadData_valid <= op_bit();
    q64_io_allocate_bits_info_QoS <= 4'($urandom());
    q64_io_allocate_bits_info_TgtID <= 11'($urandom());
    q64_io_allocate_bits_info_SrcID <= 11'($urandom());
    q64_io_allocate_bits_info_TxnID <= 12'($urandom());
    q64_io_allocate_bits_info_ReturnNID <= 11'($urandom());
    q64_io_allocate_bits_info_ReturnTxnID <= 12'($urandom());
    q64_io_allocate_bits_operand_chi_Addr <= 48'($urandom());
    q64_io_allocate_bits_operand_chi_WriteFull <= op_bit();
    q64_io_allocate_bits_operand_chi_WritePtl <= op_bit();
    q64_io_allocate_bits_operand_chi_Critical_0 <= 1'($urandom());
    q64_io_allocate_bits_operand_chi_Critical_1 <= 1'($urandom());
    q64_io_allocate_bits_operand_chi_Count <= ($urandom_range(0,1) == 0) ? 1'b0 : 1'b1;
    q64_io_allocate_bits_operand_axi_Addr <= 49'($urandom());
    q64_io_allocate_bits_operand_axi_Size <= 3'($urandom());
    q64_io_allocate_bits_operand_axi_Len <= 8'($urandom());
    q64_io_allocate_bits_operand_axi_Critical_0 <= 1'($urandom());
    q64_io_allocate_bits_operand_axi_Critical_1 <= 1'($urandom());
    q64_io_allocate_bits_operand_axi_Count <= 1'($urandom());
    q64_io_upstreamTxRsp_opDone_bits_Comp <= ($urandom_range(0,99) < 60);
    q64_io_upstreamTxRsp_opDone_bits_DBIDResp <= ($urandom_range(0,99) < 60);
    q64_io_upstreamTxRsp_opDone_bits_CompDBIDResp <= ($urandom_range(0,99) < 60);
    q64_io_upstreamTxRsp_opDone_bits_ReadReceipt <= ($urandom_range(0,99) < 60);
    q64_io_upstreamTxDat_opDone_bits_CompData <= ($urandom_range(0,99) < 60);
    q64_io_upstreamTxDat_operandWrite_bits_Critical_0 <= 1'($urandom());
    q64_io_upstreamTxDat_operandWrite_bits_Critical_1 <= 1'($urandom());
    q64_io_upstreamTxDat_operandWrite_bits_Count <= ($urandom_range(0,1) == 0) ? 1'b0 : 1'b1;
    q64_io_downstreamW_operandWrite_bits_Critical_0 <= 1'($urandom());
    q64_io_downstreamW_operandWrite_bits_Critical_1 <= 1'($urandom());
    q64_io_downstreamW_operandWrite_bits_Count <= 1'($urandom());
    q64_io_downstreamR_operandAXIWrite_bits_Critical_0 <= 1'($urandom());
    q64_io_downstreamR_operandAXIWrite_bits_Critical_1 <= 1'($urandom());
    q64_io_downstreamR_operandAXIWrite_bits_Count <= 1'($urandom());
    q64_io_allocate_bits_order_valid <= ($urandom_range(0,99) < 45);
    q64_io_allocate_bits_order_index <= ($urandom_range(0,99) < 65) ? 6'($urandom_range(0,3)) : 6'($urandom_range(0, 64 - 1));
    if (q64_drain != 0) begin
      // 排空期间把两组 Count 与所有 done 位钉死，免得随机值把排空打断
      q64_io_upstreamTxDat_operandWrite_bits_Count <= 1'b0;
      q64_io_upstreamTxRsp_opDone_bits_Comp <= 1'b1;
      q64_io_upstreamTxRsp_opDone_bits_DBIDResp <= 1'b1;
      q64_io_upstreamTxRsp_opDone_bits_CompDBIDResp <= 1'b1;
      q64_io_upstreamTxRsp_opDone_bits_ReadReceipt <= 1'b1;
      q64_io_upstreamTxDat_opDone_bits_CompData <= 1'b1;
    end
  end

  always @(negedge clk) if (cmp_en && !rst) begin
