  longint cov_q64_alloc_beats_free = 0;
  longint cov_q64_double_alloc = 0;
  longint cov_q64_clear_beats_alloc = 0;
  longint cov_q64_cancel_and_bresp = 0;
  longint cov_q64_axi_r_w_clash = 0;
  longint cov_q64_axi_w_alloc_clash = 0;
  longint cov_q64_chi_w_alloc_clash = 0;
  longint cov_q64_compdata_cnt0 = 0;
  longint cov_q64_compdata_cnt1 = 0;
  longint cov_q64_queue_full = 0;
  longint cov_q64_queue_empty = 0;
  longint cov_q64_read_multihot = 0;
  longint cov_q64_read_zero = 0;
  longint cov_q64_dangling_bresp = 0;
  longint cov_q64_ponr_and_alloc = 0;
  longint cov_q64_order_alloc_kill = 0;
  longint cov_q64_order_free_clear = 0;
  longint cov_q64_order_blocks = 0;
  always @(posedge clk) if (cmp_en && !rst) begin
    if (|(q64_alloc_hit & g_q64_free_strb)) cov_q64_alloc_beats_free++;
    if (|g_q64_dbg_double_allocation) cov_q64_double_alloc++;
    if (|(q64_alloc_hit & ((q64_txrsp_op_done_strb & {64{q64_io_upstreamTxRsp_opDone_bits_Comp | q64_io_upstreamTxRsp_opDone_bits_DBIDResp | q64_io_upstreamTxRsp_opDone_bits_CompDBIDResp | q64_io_upstreamTxRsp_opDone_bits_ReadReceipt}})
                          | q64_aw_op_ponr_strb
                          | q64_w_op_ponr_strb
                          | q64_ar_op_ponr_strb
                          | q64_b_op_done_strb
                          | q64_r_op_done_strb
                          | ({64{q64_io_upstreamRxDat_cancel_en}} & q64_rxdat_cancel_strb)))) cov_q64_clear_beats_alloc++;
    if (|(({64{q64_io_upstreamRxDat_cancel_en}} & q64_rxdat_cancel_strb)
          & q64_b_op_done_strb)) cov_q64_cancel_and_bresp++;
    if (|(q64_r_operand_axi_write_strb & q64_w_operand_write_strb))
      cov_q64_axi_r_w_clash++;
    if (|(q64_w_operand_write_strb & q64_alloc_hit)) cov_q64_axi_w_alloc_clash++;
    if (|(q64_txdat_operand_write_strb & q64_alloc_hit))
      cov_q64_chi_w_alloc_clash++;
    if (q64_io_upstreamTxDat_opDone_bits_CompData) begin
      if (|(q64_txdat_op_done_strb & ~g_q64_chi_count)) cov_q64_compdata_cnt0++;
      if (|(q64_txdat_op_done_strb &  g_q64_chi_count)) cov_q64_compdata_cnt1++;
    end
    if (&g_q64_entry_valid) cov_q64_queue_full++;
    if (~|g_q64_entry_valid) cov_q64_queue_empty++;
    if ($countones(q64_txdat_operand_read_strb) > 1) cov_q64_read_multihot++;
    if (q64_txdat_operand_read_strb == '0) cov_q64_read_zero++;
    if (|g_q64_dbg_dangling_axi_write_response) cov_q64_dangling_bresp++;
    if (|((q64_aw_op_ponr_strb | q64_w_op_ponr_strb | q64_ar_op_ponr_strb)
          & q64_alloc_hit)) cov_q64_ponr_and_alloc++;
    if (q64_io_allocate_en && q64_io_allocate_bits_order_valid) begin
      for (int j = 0; j < 64; j++)
        if (g_q64_free_strb[j] && q64_io_allocate_bits_order_index == 6'(j)
            && |(q64_alloc_strb & ~(64'd1 << j)))
          cov_q64_order_alloc_kill++;
    end
    for (int i = 0; i < 64; i++)
      for (int j = 0; j < 64; j++)
        if (i != j && g_q64_order_valid[i] && g_q64_free_strb[j]
            && g_q64_order_index[i] == 6'(j))
          cov_q64_order_free_clear++;
    if (|g_q64_order_valid) cov_q64_order_blocks++;
  end

  // =========================================================================
  // NCBTransactionQueue_1 —— CHI→AXI 的 **MMIO 桥**（Top.scala chi_mmioBridge_opt，每核一份）；32 槽，HAS_ORDER=0 HAS_DEVICE=1 HAS_AR_READY_BARRIER=1
  // =========================================================================
  localparam int Q32_N = 32;
