  always @(negedge clk) begin
    q32_focus = ($urandom_range(0, 99) < 65) ? $urandom_range(0, 3)
                                             : $urandom_range(0, 32 - 1);
    if (warm < 2) begin
      // 暖机：一拍把每个槽都分配一遍，把 20 个不复位寄存器写成确定值；
      // 其余 strobe / en 全 0，免得 op 位的次态去读还是 X 的 Count。
      q32_io_allocate_en  <= 1'b1;
      q32_alloc_strb      <= {32{1'b1}};
      q32_rxdat_query_strb <= '0;
      q32_rxdat_cancel_strb <= '0;
