      q32_txdat_operand_write_strb <= '0;
      q32_aw_op_ponr_strb <= '0;
      q32_aw_info_read_strb <= '0;
      q32_aw_operand_read_strb <= '0;
      q32_w_op_ponr_strb <= '0;
      q32_w_operand_read_strb <= '0;
      q32_w_operand_write_strb <= '0;
      q32_b_op_done_strb <= '0;
      q32_ar_op_ponr_strb <= '0;
      q32_ar_op_done_strb <= '0;
      q32_ar_info_read_strb <= '0;
      q32_ar_operand_read_strb <= '0;
      q32_r_op_done_strb <= '0;
      q32_r_operand_read_strb <= '0;
      q32_r_operand_axi_write_strb <= '0;
      q32_io_upstreamRxDat_query_en <= 1'b0;
      q32_io_upstreamRxDat_cancel_en <= 1'b0;
      q32_io_upstreamRxDat_writeData_en <= 1'b0;
    end else if (q32_drain == 3) begin
      // 排空第 1 拍：把所有槽的 chi Count 写成 0 —— CompData 的清除只在
      // Count==0 时发生，不先压平就永远排不空。
      q32_io_allocate_en <= 1'b0;
      q32_alloc_strb <= '0;
      q32_txdat_operand_write_strb <= {32{1'b1}};
      q32_rxdat_query_strb <= '0;
      q32_rxdat_cancel_strb <= '0;
      q32_rxdat_write_data_strb <= '0;
      q32_txrsp_op_read_strb <= '0;
      q32_txrsp_op_done_strb <= '0;
      q32_txrsp_info_read_strb <= '0;
      q32_txdat_op_read_strb <= '0;
      q32_txdat_op_done_strb <= '0;
      q32_txdat_info_read_strb <= '0;
      q32_txdat_operand_read_strb <= '0;
      q32_aw_op_ponr_strb <= '0;
      q32_aw_info_read_strb <= '0;
      q32_aw_operand_read_strb <= '0;
      q32_w_op_ponr_strb <= '0;
      q32_w_operand_read_strb <= '0;
      q32_w_operand_write_strb <= '0;
      q32_b_op_done_strb <= '0;
      q32_ar_op_ponr_strb <= '0;
      q32_ar_op_done_strb <= '0;
      q32_ar_info_read_strb <= '0;
      q32_ar_operand_read_strb <= '0;
      q32_r_op_done_strb <= '0;
      q32_r_operand_read_strb <= '0;
      q32_r_operand_axi_write_strb <= '0;
      q32_io_upstreamRxDat_query_en <= 1'b0;
      q32_io_upstreamRxDat_cancel_en <= 1'b0;
      q32_io_upstreamRxDat_writeData_en <= 1'b0;
      q32_drain <= q32_drain - 1;
    end else if (q32_drain != 0) begin
      // 排空第 2/3 拍：所有清除 strobe 全 1、所有 done 位全 1、Cancel 也拉起，
      // 两拍后 op 位全清、free_strb 全 1，再一拍 valid 全清 —— 队列见底。
      // 这也是**多热 strobe** 的重灾区，正好顺带打 ParallelMux 的非一热行为。
      q32_io_allocate_en <= 1'b0;
      q32_alloc_strb <= '0;
      q32_rxdat_query_strb <= {32{1'b1}};
      q32_rxdat_cancel_strb <= {32{1'b1}};
      q32_rxdat_write_data_strb <= {32{1'b1}};
      q32_txrsp_op_read_strb <= {32{1'b1}};
      q32_txrsp_op_done_strb <= {32{1'b1}};
      q32_txrsp_info_read_strb <= {32{1'b1}};
      q32_txdat_op_read_strb <= {32{1'b1}};
      q32_txdat_op_done_strb <= {32{1'b1}};
      q32_txdat_info_read_strb <= {32{1'b1}};
      q32_txdat_operand_read_strb <= {32{1'b1}};
      q32_txdat_operand_write_strb <= {32{1'b1}};
      q32_aw_op_ponr_strb <= {32{1'b1}};
      q32_aw_info_read_strb <= {32{1'b1}};
      q32_aw_operand_read_strb <= {32{1'b1}};
      q32_w_op_ponr_strb <= {32{1'b1}};
      q32_w_operand_read_strb <= {32{1'b1}};
      q32_w_operand_write_strb <= {32{1'b1}};
      q32_b_op_done_strb <= {32{1'b1}};
      q32_ar_op_ponr_strb <= {32{1'b1}};
      q32_ar_op_done_strb <= {32{1'b1}};
      q32_ar_info_read_strb <= {32{1'b1}};
      q32_ar_operand_read_strb <= {32{1'b1}};
      q32_r_op_done_strb <= {32{1'b1}};
      q32_r_operand_read_strb <= {32{1'b1}};
      q32_r_operand_axi_write_strb <= {32{1'b1}};
      q32_io_upstreamRxDat_query_en <= 1'b1;
      q32_io_upstreamRxDat_cancel_en <= 1'b1;
      q32_io_upstreamRxDat_writeData_en <= 1'b1;
      q32_drain <= q32_drain - 1;
    end else begin
      q32_io_allocate_en <= ($urandom_range(0, 99) < 55);
      q32_alloc_strb <= strb_pick(32, q32_focus);
      q32_rxdat_query_strb <= strb_pick(32, q32_focus);
      q32_rxdat_cancel_strb <= strb_pick(32, q32_focus);
      q32_rxdat_write_data_strb <= strb_pick(32, q32_focus);
      q32_txrsp_op_read_strb <= strb_pick(32, q32_focus);
      q32_txrsp_op_done_strb <= strb_pick(32, q32_focus);
      q32_txrsp_info_read_strb <= strb_pick(32, q32_focus);
      q32_txdat_op_read_strb <= strb_pick(32, q32_focus);
      q32_txdat_op_done_strb <= strb_pick(32, q32_focus);
      q32_txdat_info_read_strb <= strb_pick(32, q32_focus);
      q32_txdat_operand_read_strb <= strb_pick(32, q32_focus);
      q32_txdat_operand_write_strb <= strb_pick(32, q32_focus);
      q32_aw_op_ponr_strb <= strb_pick(32, q32_focus);
      q32_aw_info_read_strb <= strb_pick(32, q32_focus);
      q32_aw_operand_read_strb <= strb_pick(32, q32_focus);
      q32_w_op_ponr_strb <= strb_pick(32, q32_focus);
      q32_w_operand_read_strb <= strb_pick(32, q32_focus);
      q32_w_operand_write_strb <= strb_pick(32, q32_focus);
      q32_b_op_done_strb <= strb_pick(32, q32_focus);
      q32_ar_op_ponr_strb <= strb_pick(32, q32_focus);
      q32_ar_op_done_strb <= strb_pick(32, q32_focus);
      q32_ar_info_read_strb <= strb_pick(32, q32_focus);
      q32_ar_operand_read_strb <= strb_pick(32, q32_focus);
      q32_r_op_done_strb <= strb_pick(32, q32_focus);
      q32_r_operand_read_strb <= strb_pick(32, q32_focus);
      q32_r_operand_axi_write_strb <= strb_pick(32, q32_focus);
      q32_io_upstreamRxDat_query_en <= ($urandom_range(0, 99) < 50);
      q32_io_upstreamRxDat_cancel_en <= ($urandom_range(0, 99) < 50);
      q32_io_upstreamRxDat_writeData_en <= ($urandom_range(0, 99) < 50);
      // 每 ~125 拍来一次三拍排空突发：没有它，被暖机填满的 64 个槽里
      // 焦点池之外的那些永远等不到 done，队列全空/见底这类边界一次也打不到。
      if ($urandom_range(0, 999) < 8) q32_drain <= 3;
    end
    // 载荷与 op 位每拍都换（暖机/排空拍也换，两个 DUT 共用同一份输入）
    q32_io_allocate_bits_op_chi_Comp_valid <= op_bit();
    q32_io_allocate_bits_op_chi_Comp_barrier_CHICancelOrAXIBresp <= op_bit();
    q32_io_allocate_bits_op_chi_DBIDResp_valid <= op_bit();
    q32_io_allocate_bits_op_chi_CompDBIDResp_valid <= op_bit();
    q32_io_allocate_bits_op_chi_ReadReceipt_valid <= op_bit();
    q32_io_allocate_bits_op_chi_CompData_valid <= op_bit();
    q32_io_allocate_bits_op_chi_CompData_sep <= op_bit();
    q32_io_allocate_bits_op_axi_WriteAddress_valid <= op_bit();
    q32_io_allocate_bits_op_axi_WriteAddress_barrier_CHIWriteBackData <= op_bit();
    q32_io_allocate_bits_op_axi_WriteData_valid <= op_bit();
    q32_io_allocate_bits_op_axi_WriteResponse_valid <= op_bit();
    q32_io_allocate_bits_op_axi_ReadAddress_valid <= op_bit();
    q32_io_allocate_bits_op_axi_ReadData_valid <= op_bit();
    q32_io_allocate_bits_info_QoS <= 4'($urandom());
    q32_io_allocate_bits_info_TgtID <= 11'($urandom());
    q32_io_allocate_bits_info_SrcID <= 11'($urandom());
    q32_io_allocate_bits_info_TxnID <= 12'($urandom());
    q32_io_allocate_bits_info_ReturnNID <= 11'($urandom());
    q32_io_allocate_bits_info_ReturnTxnID <= 12'($urandom());
    q32_io_allocate_bits_operand_chi_Addr <= 48'($urandom());
    q32_io_allocate_bits_operand_chi_WriteFull <= op_bit();
    q32_io_allocate_bits_operand_chi_WritePtl <= op_bit();
    q32_io_allocate_bits_operand_chi_Critical_0 <= 1'($urandom());
    q32_io_allocate_bits_operand_chi_Critical_1 <= 1'($urandom());
    q32_io_allocate_bits_operand_chi_Count <= ($urandom_range(0,1) == 0) ? 1'b0 : 1'b1;
    q32_io_allocate_bits_operand_axi_Addr <= 49'($urandom());
    q32_io_allocate_bits_operand_axi_Size <= 3'($urandom());
    q32_io_allocate_bits_operand_axi_Len <= 8'($urandom());
    q32_io_allocate_bits_operand_axi_Critical_0 <= 1'($urandom());
    q32_io_allocate_bits_operand_axi_Critical_1 <= 1'($urandom());
    q32_io_allocate_bits_operand_axi_Count <= 1'($urandom());
    q32_io_upstreamTxRsp_opDone_bits_Comp <= ($urandom_range(0,99) < 60);
    q32_io_upstreamTxRsp_opDone_bits_DBIDResp <= ($urandom_range(0,99) < 60);
    q32_io_upstreamTxRsp_opDone_bits_CompDBIDResp <= ($urandom_range(0,99) < 60);
    q32_io_upstreamTxRsp_opDone_bits_ReadReceipt <= ($urandom_range(0,99) < 60);
    q32_io_upstreamTxDat_opDone_bits_CompData <= ($urandom_range(0,99) < 60);
    q32_io_upstreamTxDat_operandWrite_bits_Critical_0 <= 1'($urandom());
    q32_io_upstreamTxDat_operandWrite_bits_Critical_1 <= 1'($urandom());
    q32_io_upstreamTxDat_operandWrite_bits_Count <= ($urandom_range(0,1) == 0) ? 1'b0 : 1'b1;
    q32_io_downstreamW_operandWrite_bits_Critical_0 <= 1'($urandom());
    q32_io_downstreamW_operandWrite_bits_Critical_1 <= 1'($urandom());
    q32_io_downstreamW_operandWrite_bits_Count <= 1'($urandom());
    q32_io_downstreamR_operandAXIWrite_bits_Critical_0 <= 1'($urandom());
    q32_io_downstreamR_operandAXIWrite_bits_Critical_1 <= 1'($urandom());
    q32_io_downstreamR_operandAXIWrite_bits_Count <= 1'($urandom());
    q32_io_allocate_bits_operand_axi_Device <= 1'($urandom());
    if (q32_drain != 0) begin
      // 排空期间把两组 Count 与所有 done 位钉死，免得随机值把排空打断
      q32_io_upstreamTxDat_operandWrite_bits_Count <= 1'b0;
      q32_io_upstreamTxRsp_opDone_bits_Comp <= 1'b1;
      q32_io_upstreamTxRsp_opDone_bits_DBIDResp <= 1'b1;
      q32_io_upstreamTxRsp_opDone_bits_CompDBIDResp <= 1'b1;
      q32_io_upstreamTxRsp_opDone_bits_ReadReceipt <= 1'b1;
      q32_io_upstreamTxDat_opDone_bits_CompData <= 1'b1;
    end
  end

  always @(negedge clk) if (cmp_en && !rst) begin
    checks++;
    if (g_q32_free_strb !== x_q32_free_strb) begin errors++;
      if (errors < 20) $display("MISMATCH %0t q32.free_strb g=%0h x=%0h",
                                $time, g_q32_free_strb, x_q32_free_strb); end
    checks++;
    if (g_q32_txrsp_op_valid !== x_q32_txrsp_op_valid) begin errors++;
      if (errors < 20) $display("MISMATCH %0t q32.txrsp_op_valid g=%0h x=%0h",
                                $time, g_q32_txrsp_op_valid, x_q32_txrsp_op_valid); end
    checks++;
    if (g_q32_txdat_op_valid !== x_q32_txdat_op_valid) begin errors++;
      if (errors < 20) $display("MISMATCH %0t q32.txdat_op_valid g=%0h x=%0h",
                                $time, g_q32_txdat_op_valid, x_q32_txdat_op_valid); end
    checks++;
    if (g_q32_aw_op_valid !== x_q32_aw_op_valid) begin errors++;
      if (errors < 20) $display("MISMATCH %0t q32.aw_op_valid g=%0h x=%0h",
                                $time, g_q32_aw_op_valid, x_q32_aw_op_valid); end
    checks++;
    if (g_q32_ar_op_valid !== x_q32_ar_op_valid) begin errors++;
      if (errors < 20) $display("MISMATCH %0t q32.ar_op_valid g=%0h x=%0h",
                                $time, g_q32_ar_op_valid, x_q32_ar_op_valid); end
    checks++;
    if (g_q32_dbg_double_allocation !== x_q32_dbg_double_allocation) begin errors++;
      if (errors < 20) $display("MISMATCH %0t q32.dbg_double_allocation g=%0h x=%0h",
                                $time, g_q32_dbg_double_allocation, x_q32_dbg_double_allocation); end
    checks++;
    if (g_q32_dbg_dangling_axi_write_response !== x_q32_dbg_dangling_axi_write_response) begin errors++;
      if (errors < 20) $display("MISMATCH %0t q32.dbg_dangling_axi_write_response g=%0h x=%0h",
                                $time, g_q32_dbg_dangling_axi_write_response, x_q32_dbg_dangling_axi_write_response); end
    checks++;
    if (g_q32_txdat_crit !== x_q32_txdat_crit) begin errors++;
      if (errors < 20) $display("MISMATCH %0t q32.txdat_opValid_Critical g=%0h x=%0h",
                                $time, g_q32_txdat_crit, x_q32_txdat_crit); end
    checks++;
    if (g_q32_io_upstreamRxDat_query_result_valid !== x_q32_io_upstreamRxDat_query_result_valid) begin errors++;
      if (errors < 20) $display("MISMATCH %0t q32.io_upstreamRxDat_query_result_valid g=%0h x=%0h",
                                $time, g_q32_io_upstreamRxDat_query_result_valid, x_q32_io_upstreamRxDat_query_result_valid); end
    checks++;
    if (g_q32_io_upstreamRxDat_query_result_WriteFull !== x_q32_io_upstreamRxDat_query_result_WriteFull) begin errors++;
      if (errors < 20) $display("MISMATCH %0t q32.io_upstreamRxDat_query_result_WriteFull g=%0h x=%0h",
                                $time, g_q32_io_upstreamRxDat_query_result_WriteFull, x_q32_io_upstreamRxDat_query_result_WriteFull); end
    checks++;
    if (g_q32_io_upstreamRxDat_query_result_WritePtl !== x_q32_io_upstreamRxDat_query_result_WritePtl) begin errors++;
      if (errors < 20) $display("MISMATCH %0t q32.io_upstreamRxDat_query_result_WritePtl g=%0h x=%0h",
                                $time, g_q32_io_upstreamRxDat_query_result_WritePtl, x_q32_io_upstreamRxDat_query_result_WritePtl); end
    checks++;
    if (g_q32_io_upstreamTxRsp_opRead_bits_Comp !== x_q32_io_upstreamTxRsp_opRead_bits_Comp) begin errors++;
      if (errors < 20) $display("MISMATCH %0t q32.io_upstreamTxRsp_opRead_bits_Comp g=%0h x=%0h",
                                $time, g_q32_io_upstreamTxRsp_opRead_bits_Comp, x_q32_io_upstreamTxRsp_opRead_bits_Comp); end
    checks++;
    if (g_q32_io_upstreamTxRsp_opRead_bits_DBIDResp !== x_q32_io_upstreamTxRsp_opRead_bits_DBIDResp) begin errors++;
      if (errors < 20) $display("MISMATCH %0t q32.io_upstreamTxRsp_opRead_bits_DBIDResp g=%0h x=%0h",
                                $time, g_q32_io_upstreamTxRsp_opRead_bits_DBIDResp, x_q32_io_upstreamTxRsp_opRead_bits_DBIDResp); end
    checks++;
    if (g_q32_io_upstreamTxRsp_opRead_bits_CompDBIDResp !== x_q32_io_upstreamTxRsp_opRead_bits_CompDBIDResp) begin errors++;
      if (errors < 20) $display("MISMATCH %0t q32.io_upstreamTxRsp_opRead_bits_CompDBIDResp g=%0h x=%0h",
                                $time, g_q32_io_upstreamTxRsp_opRead_bits_CompDBIDResp, x_q32_io_upstreamTxRsp_opRead_bits_CompDBIDResp); end
    checks++;
    if (g_q32_io_upstreamTxRsp_opRead_bits_ReadReceipt !== x_q32_io_upstreamTxRsp_opRead_bits_ReadReceipt) begin errors++;
      if (errors < 20) $display("MISMATCH %0t q32.io_upstreamTxRsp_opRead_bits_ReadReceipt g=%0h x=%0h",
