    checks++;
    if (g_q32_io_upstreamTxDat_opRead_bits_CompData_sep !== x_q32_io_upstreamTxDat_opRead_bits_CompData_sep) begin errors++;
      if (errors < 20) $display("MISMATCH %0t q32.io_upstreamTxDat_opRead_bits_CompData_sep g=%0h x=%0h",
                                $time, g_q32_io_upstreamTxDat_opRead_bits_CompData_sep, x_q32_io_upstreamTxDat_opRead_bits_CompData_sep); end
    checks++;
    if (g_q32_io_upstreamTxDat_infoRead_bits_QoS !== x_q32_io_upstreamTxDat_infoRead_bits_QoS) begin errors++;
      if (errors < 20) $display("MISMATCH %0t q32.io_upstreamTxDat_infoRead_bits_QoS g=%0h x=%0h",
