    checks++;
    if (g_q32_io_upstreamTxDat_infoRead_bits_SrcID !== x_q32_io_upstreamTxDat_infoRead_bits_SrcID) begin errors++;
      if (errors < 20) $display("MISMATCH %0t q32.io_upstreamTxDat_infoRead_bits_SrcID g=%0h x=%0h",
