    checks++;
    if (g_q32_io_upstreamTxDat_infoRead_bits_TxnID !== x_q32_io_upstreamTxDat_infoRead_bits_TxnID) begin errors++;
      if (errors < 20) $display("MISMATCH %0t q32.io_upstreamTxDat_infoRead_bits_TxnID g=%0h x=%0h",
                                $time, g_q32_io_upstreamTxDat_infoRead_bits_TxnID, x_q32_io_upstreamTxDat_infoRead_bits_TxnID); end
    checks++;
    if (g_q32_io_upstreamTxDat_operandRead_bits_Addr !== x_q32_io_upstreamTxDat_operandRead_bits_Addr) begin errors++;
      if (errors < 20) $display("MISMATCH %0t q32.io_upstreamTxDat_operandRead_bits_Addr g=%0h x=%0h",
                                $time, g_q32_io_upstreamTxDat_operandRead_bits_Addr, x_q32_io_upstreamTxDat_operandRead_bits_Addr); end
    checks++;
    if (g_q32_io_upstreamTxDat_operandRead_bits_ReadRespErr !== x_q32_io_upstreamTxDat_operandRead_bits_ReadRespErr) begin errors++;
