                                $time, g_q32_io_downstreamAw_operandRead_bits_Addr, x_q32_io_downstreamAw_operandRead_bits_Addr); end
    checks++;
    if (g_q32_io_downstreamAw_operandRead_bits_Burst !== x_q32_io_downstreamAw_operandRead_bits_Burst) begin errors++;
      if (errors < 20) $display("MISMATCH %0t q32.io_downstreamAw_operandRead_bits_Burst g=%0h x=%0h",
                                $time, g_q32_io_downstreamAw_operandRead_bits_Burst, x_q32_io_downstreamAw_operandRead_bits_Burst); end
    checks++;
    if (g_q32_io_downstreamAw_operandRead_bits_Size !== x_q32_io_downstreamAw_operandRead_bits_Size) begin errors++;
      if (errors < 20) $display("MISMATCH %0t q32.io_downstreamAw_operandRead_bits_Size g=%0h x=%0h",
                                $time, g_q32_io_downstreamAw_operandRead_bits_Size, x_q32_io_downstreamAw_operandRead_bits_Size); end
    checks++;
    if (g_q32_io_downstreamAw_operandRead_bits_Len !== x_q32_io_downstreamAw_operandRead_bits_Len) begin errors++;
      if (errors < 20) $display("MISMATCH %0t q32.io_downstreamAw_operandRead_bits_Len g=%0h x=%0h",
                                $time, g_q32_io_downstreamAw_operandRead_bits_Len, x_q32_io_downstreamAw_operandRead_bits_Len); end
    checks++;
    if (g_q32_io_downstreamW_operandRead_bits_Critical_0 !== x_q32_io_downstreamW_operandRead_bits_Critical_0) begin errors++;
      if (errors < 20) $display("MISMATCH %0t q32.io_downstreamW_operandRead_bits_Critical_0 g=%0h x=%0h",
                                $time, g_q32_io_downstreamW_operandRead_bits_Critical_0, x_q32_io_downstreamW_operandRead_bits_Critical_0); end
    checks++;
    if (g_q32_io_downstreamW_operandRead_bits_Critical_1 !== x_q32_io_downstreamW_operandRead_bits_Critical_1) begin errors++;
      if (errors < 20) $display("MISMATCH %0t q32.io_downstreamW_operandRead_bits_Critical_1 g=%0h x=%0h",
                                $time, g_q32_io_downstreamW_operandRead_bits_Critical_1, x_q32_io_downstreamW_operandRead_bits_Critical_1); end
    checks++;
    if (g_q32_io_downstreamW_operandRead_bits_Count !== x_q32_io_downstreamW_operandRead_bits_Count) begin errors++;
      if (errors < 20) $display("MISMATCH %0t q32.io_downstreamW_operandRead_bits_Count g=%0h x=%0h",
                                $time, g_q32_io_downstreamW_operandRead_bits_Count, x_q32_io_downstreamW_operandRead_bits_Count); end
    checks++;
    if (g_q32_io_downstreamAr_infoRead_bits_QoS !== x_q32_io_downstreamAr_infoRead_bits_QoS) begin errors++;
      if (errors < 20) $display("MISMATCH %0t q32.io_downstreamAr_infoRead_bits_QoS g=%0h x=%0h",
                                $time, g_q32_io_downstreamAr_infoRead_bits_QoS, x_q32_io_downstreamAr_infoRead_bits_QoS); end
    checks++;
    if (g_q32_io_downstreamAr_operandRead_bits_Addr !== x_q32_io_downstreamAr_operandRead_bits_Addr) begin errors++;
      if (errors < 20) $display("MISMATCH %0t q32.io_downstreamAr_operandRead_bits_Addr g=%0h x=%0h",
                                $time, g_q32_io_downstreamAr_operandRead_bits_Addr, x_q32_io_downstreamAr_operandRead_bits_Addr); end
    checks++;
    if (g_q32_io_downstreamAr_operandRead_bits_Burst !== x_q32_io_downstreamAr_operandRead_bits_Burst) begin errors++;
      if (errors < 20) $display("MISMATCH %0t q32.io_downstreamAr_operandRead_bits_Burst g=%0h x=%0h",
                                $time, g_q32_io_downstreamAr_operandRead_bits_Burst, x_q32_io_downstreamAr_operandRead_bits_Burst); end
    checks++;
    if (g_q32_io_downstreamAr_operandRead_bits_Size !== x_q32_io_downstreamAr_operandRead_bits_Size) begin errors++;
      if (errors < 20) $display("MISMATCH %0t q32.io_downstreamAr_operandRead_bits_Size g=%0h x=%0h",
                                $time, g_q32_io_downstreamAr_operandRead_bits_Size, x_q32_io_downstreamAr_operandRead_bits_Size); end
    checks++;
    if (g_q32_io_downstreamAr_operandRead_bits_Len !== x_q32_io_downstreamAr_operandRead_bits_Len) begin errors++;
      if (errors < 20) $display("MISMATCH %0t q32.io_downstreamAr_operandRead_bits_Len g=%0h x=%0h",
                                $time, g_q32_io_downstreamAr_operandRead_bits_Len, x_q32_io_downstreamAr_operandRead_bits_Len); end
    checks++;
    if (g_q32_io_downstreamAr_operandRead_bits_Device !== x_q32_io_downstreamAr_operandRead_bits_Device) begin errors++;
      if (errors < 20) $display("MISMATCH %0t q32.io_downstreamAr_operandRead_bits_Device g=%0h x=%0h",
                                $time, g_q32_io_downstreamAr_operandRead_bits_Device, x_q32_io_downstreamAr_operandRead_bits_Device); end
    checks++;
    if (g_q32_io_downstreamR_operandRead_bits_Critical_0 !== x_q32_io_downstreamR_operandRead_bits_Critical_0) begin errors++;
      if (errors < 20) $display("MISMATCH %0t q32.io_downstreamR_operandRead_bits_Critical_0 g=%0h x=%0h",
                                $time, g_q32_io_downstreamR_operandRead_bits_Critical_0, x_q32_io_downstreamR_operandRead_bits_Critical_0); end
    checks++;
    if (g_q32_io_downstreamR_operandRead_bits_Critical_1 !== x_q32_io_downstreamR_operandRead_bits_Critical_1) begin errors++;
      if (errors < 20) $display("MISMATCH %0t q32.io_downstreamR_operandRead_bits_Critical_1 g=%0h x=%0h",
                                $time, g_q32_io_downstreamR_operandRead_bits_Critical_1, x_q32_io_downstreamR_operandRead_bits_Critical_1); end
    checks++;
    if (g_q32_io_downstreamR_operandRead_bits_Count !== x_q32_io_downstreamR_operandRead_bits_Count) begin errors++;
      if (errors < 20) $display("MISMATCH %0t q32.io_downstreamR_operandRead_bits_Count g=%0h x=%0h",
                                $time, g_q32_io_downstreamR_operandRead_bits_Count, x_q32_io_downstreamR_operandRead_bits_Count); end
  end

  longint cov_q32_alloc_beats_free = 0;
  longint cov_q32_double_alloc = 0;
  longint cov_q32_clear_beats_alloc = 0;
  longint cov_q32_cancel_and_bresp = 0;
  longint cov_q32_axi_r_w_clash = 0;
  longint cov_q32_axi_w_alloc_clash = 0;
  longint cov_q32_chi_w_alloc_clash = 0;
  longint cov_q32_compdata_cnt0 = 0;
  longint cov_q32_compdata_cnt1 = 0;
  longint cov_q32_queue_full = 0;
  longint cov_q32_queue_empty = 0;
  longint cov_q32_read_multihot = 0;
  longint cov_q32_read_zero = 0;
  longint cov_q32_dangling_bresp = 0;
  longint cov_q32_ponr_and_alloc = 0;
  longint cov_q32_ar_barrier_clear = 0;
  longint cov_q32_ar_barrier_set = 0;
  longint cov_q32_device_read = 0;
  always @(posedge clk) if (cmp_en && !rst) begin
    if (|(q32_alloc_hit & g_q32_free_strb)) cov_q32_alloc_beats_free++;
    if (|g_q32_dbg_double_allocation) cov_q32_double_alloc++;
    if (|(q32_alloc_hit & ((q32_txrsp_op_done_strb & {32{q32_io_upstreamTxRsp_opDone_bits_Comp | q32_io_upstreamTxRsp_opDone_bits_DBIDResp | q32_io_upstreamTxRsp_opDone_bits_CompDBIDResp | q32_io_upstreamTxRsp_opDone_bits_ReadReceipt}})
                          | q32_aw_op_ponr_strb
                          | q32_w_op_ponr_strb
                          | q32_ar_op_ponr_strb
                          | q32_b_op_done_strb
                          | q32_r_op_done_strb
                          | ({32{q32_io_upstreamRxDat_cancel_en}} & q32_rxdat_cancel_strb)))) cov_q32_clear_beats_alloc++;
    if (|(({32{q32_io_upstreamRxDat_cancel_en}} & q32_rxdat_cancel_strb)
          & q32_b_op_done_strb)) cov_q32_cancel_and_bresp++;
    if (|(q32_r_operand_axi_write_strb & q32_w_operand_write_strb))
      cov_q32_axi_r_w_clash++;
    if (|(q32_w_operand_write_strb & q32_alloc_hit)) cov_q32_axi_w_alloc_clash++;
    if (|(q32_txdat_operand_write_strb & q32_alloc_hit))
      cov_q32_chi_w_alloc_clash++;
    if (q32_io_upstreamTxDat_opDone_bits_CompData) begin
      if (|(q32_txdat_op_done_strb & ~g_q32_chi_count)) cov_q32_compdata_cnt0++;
      if (|(q32_txdat_op_done_strb &  g_q32_chi_count)) cov_q32_compdata_cnt1++;
    end
    if (&g_q32_entry_valid) cov_q32_queue_full++;
    if (~|g_q32_entry_valid) cov_q32_queue_empty++;
    if ($countones(q32_txdat_operand_read_strb) > 1) cov_q32_read_multihot++;
    if (q32_txdat_operand_read_strb == '0) cov_q32_read_zero++;
    if (|g_q32_dbg_dangling_axi_write_response) cov_q32_dangling_bresp++;
    if (|((q32_aw_op_ponr_strb | q32_w_op_ponr_strb | q32_ar_op_ponr_strb)
          & q32_alloc_hit)) cov_q32_ponr_and_alloc++;
    if (|(q32_ar_op_done_strb & g_q32_rr_barrier)) cov_q32_ar_barrier_clear++;
    if (|g_q32_rr_barrier) cov_q32_ar_barrier_set++;
    if (g_q32_io_downstreamAr_operandRead_bits_Device) cov_q32_device_read++;
  end


  // -------------------------------------------------------------------------
  // 复位 / 暖机 / 收尾
  // -------------------------------------------------------------------------
  initial begin
    if ($value$plusargs("ncycles=%d", NCYCLES)) ;
    rst = 1'b1;
    repeat (4) @(posedge clk);
    @(negedge clk) rst = 1'b0;
    // 暖机：复位撤销后再给两拍「全槽分配」，把 20 个不复位寄存器写成确定值。
    // warm 在 posedge 上改，激励块在 negedge 上读，避开同沿竞争。
    repeat (2) @(posedge clk);
    warm = 2;
    repeat (2) @(posedge clk);
    @(negedge clk) cmp_en = 1'b1;
    // ★中途反复打异步复位★：这是复位域的唯一把关手段。
    // 暖机之后两轮 initreg 必然都绿（不复位的 20 个寄存器都已写成确定值），
    // 所以「复位域对不对」只能靠复位事件本身来测：复位后 valid 与 op 位必须归 0、
    // 而 info/operand/order 必须**保持不变** —— 任何一侧多复位或少复位都会当场失配。
    // 只打一次的话余量太薄：实测「去掉 op_comp_valid 的复位」这个变异在单次复位下
    // 只报 16 个 errors，换个 seed 就可能漏。这里打 RESET_PULSES 次。
    for (int k = 0; k < RESET_PULSES; k++) begin
      repeat (NCYCLES / RESET_PULSES) @(posedge clk);
      @(negedge clk) begin rst = 1'b1; cmp_en = 1'b0; end
      repeat (1 + (k % 3)) @(posedge clk);
      @(negedge clk) rst = 1'b0;
      repeat (2) @(posedge clk);
      @(negedge clk) cmp_en = 1'b1;
      cov_reset_pulses++;
    end

    $display("--- COVERAGE (每项必须 > 0，否则该机制没被激励到) ---");
    $display("  %-34s: %0d", "中途异步复位次数（复位域的唯一把关手段）", cov_reset_pulses);
    $display("  %-34s: %0d", "[q64] 分配压过释放(同槽同拍)", cov_q64_alloc_beats_free);
    $display("  %-34s: %0d", "[q64] 占用中的槽又被分配", cov_q64_double_alloc);
    $display("  %-34s: %0d", "[q64] 清除压过分配(同槽同拍)", cov_q64_clear_beats_alloc);
    $display("  %-34s: %0d", "[q64] Cancel 与 BRESP 同槽同拍", cov_q64_cancel_and_bresp);
    $display("  %-34s: %0d", "[q64] R/W 抢同一份 axi Critical", cov_q64_axi_r_w_clash);
    $display("  %-34s: %0d", "[q64] W/allocate 抢 axi Critical", cov_q64_axi_w_alloc_clash);
    $display("  %-34s: %0d", "[q64] TXDAT/allocate 抢 chi Critical", cov_q64_chi_w_alloc_clash);
    $display("  %-34s: %0d", "[q64] CompData done 且 Count=0(真清除)", cov_q64_compdata_cnt0);
    $display("  %-34s: %0d", "[q64] CompData done 但 Count!=0(不清除)", cov_q64_compdata_cnt1);
    $display("  %-34s: %0d", "[q64] 队列全满", cov_q64_queue_full);
    $display("  %-34s: %0d", "[q64] 队列全空", cov_q64_queue_empty);
    $display("  %-34s: %0d", "[q64] 读口多热(OR 多路)", cov_q64_read_multihot);
    $display("  %-34s: %0d", "[q64] 读口全零", cov_q64_read_zero);
    $display("  %-34s: %0d", "[q64] 悬空 BRESP 断言条件", cov_q64_dangling_bresp);
    $display("  %-34s: %0d", "[q64] PoNR 与分配同槽同拍", cov_q64_ponr_and_alloc);
    $display("  %-34s: %0d", "[q64] 新依赖一出生就被释放作废", cov_q64_order_alloc_kill);
    $display("  %-34s: %0d", "[q64] 已存依赖被释放解除", cov_q64_order_free_clear);
    $display("  %-34s: %0d", "[q64] 依赖挡住了冒泡", cov_q64_order_blocks);
    $display("  %-34s: %0d", "[q32] 分配压过释放(同槽同拍)", cov_q32_alloc_beats_free);
    $display("  %-34s: %0d", "[q32] 占用中的槽又被分配", cov_q32_double_alloc);
    $display("  %-34s: %0d", "[q32] 清除压过分配(同槽同拍)", cov_q32_clear_beats_alloc);
    $display("  %-34s: %0d", "[q32] Cancel 与 BRESP 同槽同拍", cov_q32_cancel_and_bresp);
    $display("  %-34s: %0d", "[q32] R/W 抢同一份 axi Critical", cov_q32_axi_r_w_clash);
    $display("  %-34s: %0d", "[q32] W/allocate 抢 axi Critical", cov_q32_axi_w_alloc_clash);
    $display("  %-34s: %0d", "[q32] TXDAT/allocate 抢 chi Critical", cov_q32_chi_w_alloc_clash);
    $display("  %-34s: %0d", "[q32] CompData done 且 Count=0(真清除)", cov_q32_compdata_cnt0);
    $display("  %-34s: %0d", "[q32] CompData done 但 Count!=0(不清除)", cov_q32_compdata_cnt1);
    $display("  %-34s: %0d", "[q32] 队列全满", cov_q32_queue_full);
    $display("  %-34s: %0d", "[q32] 队列全空", cov_q32_queue_empty);
    $display("  %-34s: %0d", "[q32] 读口多热(OR 多路)", cov_q32_read_multihot);
    $display("  %-34s: %0d", "[q32] 读口全零", cov_q32_read_zero);
    $display("  %-34s: %0d", "[q32] 悬空 BRESP 断言条件", cov_q32_dangling_bresp);
    $display("  %-34s: %0d", "[q32] PoNR 与分配同槽同拍", cov_q32_ponr_and_alloc);
    $display("  %-34s: %0d", "[q32] ARREADY 解除 ReadReceipt 屏障", cov_q32_ar_barrier_clear);
    $display("  %-34s: %0d", "[q32] ReadReceipt 屏障挂起中", cov_q32_ar_barrier_set);
    $display("  %-34s: %0d", "[q32] AR 读口读出 Device=1", cov_q32_device_read);
    $display("checks=%0d errors=%0d", checks, errors);
    if (errors == 0 &&
        cov_reset_pulses > 0 &&
        cov_q64_alloc_beats_free > 0 &&
        cov_q64_double_alloc > 0 &&
        cov_q64_clear_beats_alloc > 0 &&
        cov_q64_cancel_and_bresp > 0 &&
        cov_q64_axi_r_w_clash > 0 &&
        cov_q64_axi_w_alloc_clash > 0 &&
        cov_q64_chi_w_alloc_clash > 0 &&
        cov_q64_compdata_cnt0 > 0 &&
        cov_q64_compdata_cnt1 > 0 &&
        cov_q64_queue_full > 0 &&
        cov_q64_queue_empty > 0 &&
        cov_q64_read_multihot > 0 &&
        cov_q64_read_zero > 0 &&
        cov_q64_dangling_bresp > 0 &&
        cov_q64_ponr_and_alloc > 0 &&
        cov_q64_order_alloc_kill > 0 &&
        cov_q64_order_free_clear > 0 &&
        cov_q64_order_blocks > 0 &&
        cov_q32_alloc_beats_free > 0 &&
        cov_q32_double_alloc > 0 &&
        cov_q32_clear_beats_alloc > 0 &&
        cov_q32_cancel_and_bresp > 0 &&
        cov_q32_axi_r_w_clash > 0 &&
        cov_q32_axi_w_alloc_clash > 0 &&
        cov_q32_chi_w_alloc_clash > 0 &&
        cov_q32_compdata_cnt0 > 0 &&
        cov_q32_compdata_cnt1 > 0 &&
        cov_q32_queue_full > 0 &&
        cov_q32_queue_empty > 0 &&
        cov_q32_read_multihot > 0 &&
        cov_q32_read_zero > 0 &&
        cov_q32_dangling_bresp > 0 &&
        cov_q32_ponr_and_alloc > 0 &&
        cov_q32_ar_barrier_clear > 0 &&
        cov_q32_ar_barrier_set > 0 &&
        cov_q32_device_read > 0)
      $display("TEST PASSED");
    else
      $display("TEST FAILED (errors=%0d 或覆盖项为 0)", errors);
    $finish;
  end

endmodule
